/*
 * UiChemy interactive runtime — ships in a uichemy_composer widget's raw_js.
 *
 * Why: React event handlers/state do NOT survive the static export. The
 * browser-settle already bakes correct *initial* values (counters, etc.), but
 * ongoing behavior (accordions, tabs, carousels) is gone. This tiny vanilla
 * runtime restores it for sections that mark their structure with data-uich-*
 * hooks. It is idempotent and a complete no-op when no hooks are present, so it
 * is safe to include on every interactive section.
 *
 * Conventions (the JSX should emit these for behavior to auto-wire):
 *   Accordion:  [data-uich-accordion(="multi")]
 *                 [data-uich-acc-item] > [data-uich-acc-trigger] + [data-uich-acc-panel]
 *   Tabs:       [data-uich-tabs]
 *                 [data-uich-tab][data-uich-target="X"] ... [data-uich-panel="X"]
 *   Carousel:   [data-uich-carousel(="autoplay-ms")]
 *                 [data-uich-track] (children = slides); optional
 *                 [data-uich-prev] / [data-uich-next] / [data-uich-dot][data-uich-index]
 *   Toggle:     [data-uich-toggle] (role=switch-ish); flips data-checked
 */
(function () {
  function initAccordions(root) {
    root.querySelectorAll('[data-uich-accordion]').forEach(function (acc) {
      if (acc.__uichInit) return; acc.__uichInit = true;
      var multi = acc.getAttribute('data-uich-accordion') === 'multi';
      acc.querySelectorAll('[data-uich-acc-trigger]').forEach(function (trig) {
        trig.addEventListener('click', function () {
          var item = trig.closest('[data-uich-acc-item]');
          if (!item) return;
          var panel = item.querySelector('[data-uich-acc-panel]');
          var open = item.getAttribute('data-open') === 'true';
          if (!multi) {
            acc.querySelectorAll('[data-uich-acc-item]').forEach(function (it) {
              it.setAttribute('data-open', 'false');
              var p = it.querySelector('[data-uich-acc-panel]');
              if (p) p.style.maxHeight = '0px';
            });
          }
          item.setAttribute('data-open', String(!open));
          if (panel) panel.style.maxHeight = open ? '0px' : panel.scrollHeight + 'px';
        });
      });
    });
  }

  function initTabs(root) {
    root.querySelectorAll('[data-uich-tabs]').forEach(function (tabs) {
      if (tabs.__uichInit) return; tabs.__uichInit = true;
      var btns = tabs.querySelectorAll('[data-uich-tab]');
      function activate(target) {
        btns.forEach(function (b) { b.setAttribute('data-active', String(b.getAttribute('data-uich-target') === target)); });
        tabs.querySelectorAll('[data-uich-panel]').forEach(function (p) {
          p.style.display = p.getAttribute('data-uich-panel') === target ? '' : 'none';
        });
      }
      btns.forEach(function (b) { b.addEventListener('click', function () { activate(b.getAttribute('data-uich-target')); }); });
      if (btns[0]) activate(btns[0].getAttribute('data-uich-target'));
    });
  }

  function initCarousels(root) {
    root.querySelectorAll('[data-uich-carousel]').forEach(function (car) {
      if (car.__uichInit) return; car.__uichInit = true;
      var track = car.querySelector('[data-uich-track]');
      if (!track) return;
      var count = track.children.length;
      var i = 0;
      var dots = car.querySelectorAll('[data-uich-dot]');
      function go(n) {
        i = (n + count) % count;
        track.style.transform = 'translateX(-' + i * 100 + '%)';
        if (track.style.transition === '') track.style.transition = 'transform .4s ease';
        dots.forEach(function (d) { d.setAttribute('data-active', String(Number(d.getAttribute('data-uich-index')) === i)); });
      }
      var prev = car.querySelector('[data-uich-prev]');
      var next = car.querySelector('[data-uich-next]');
      if (prev) prev.addEventListener('click', function () { go(i - 1); });
      if (next) next.addEventListener('click', function () { go(i + 1); });
      dots.forEach(function (d) { d.addEventListener('click', function () { go(Number(d.getAttribute('data-uich-index')) || 0); }); });
      var ap = parseInt(car.getAttribute('data-uich-carousel') || '0', 10);
      if (ap > 0) setInterval(function () { go(i + 1); }, ap);
      go(0);
    });
  }

  function initToggles(root) {
    root.querySelectorAll('[data-uich-toggle]').forEach(function (t) {
      if (t.__uichInit) return; t.__uichInit = true;
      t.addEventListener('click', function () {
        t.setAttribute('data-checked', String(t.getAttribute('data-checked') !== 'true'));
      });
    });
  }

  function init() {
    var root = document;
    initAccordions(root);
    initTabs(root);
    initCarousels(root);
    initToggles(root);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

