(function () {
  function initAccordions(root) {
    root.querySelectorAll('[data-uich-accordion]').forEach(function (acc) {
      if (acc.__uichInit) return; acc.__uichInit = true;
      var multi = acc.getAttribute('data-uich-accordion') === 'multi';
      acc.querySelectorAll('[data-uich-acc-trigger]').forEach(function (trig) {
        trig.addEventListener('click', function () {
          var item = trig.closest('[data-uich-acc-item]');
          if (!item) return;
          var panel = item.querySelector('[data-uich-acc-panel]');
          var open = item.getAttribute('data-open') === 'true';
